"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 L3 (plan 6.2): the whisper-base encoder reads the 8 s window, plus L2's features that do not come straight
from the audio models, two outputs (S = stop, R = respond).

Audio: as v0.3's L3 (whisper-base rev e37978b; 800 log-mel frames -> 400 encoder frames, positional embeddings cut to
400, the whole encoder fine-tuned; attention pooling). Other inputs: the det, text and line groups of p1v4_l2.py (the
information L1 reads in its situation text: detected sounds, transcripts, speaker tags, the assistant's state and the
history; the same set as T), standardised with the training means. Head: two layers (256, GELU) on [pooled audio,
features] -> 2 logits; binary cross-entropy on the labels that are set (R only where defined).
Training as v0.3's L3: the training set, 3 epochs, batch 32, AdamW (encoder 5e-5, head 1e-3, weight decay 0.01), 300
warm-up steps then cosine, bf16 autocast, gradient clipping 1.0. The epoch is chosen on dev by the operating-point rule.
usage: python -X utf8 scripts/p1v4_l3.py train <out_dir>
"""
import json
import math
import os
import sys
import time

import numpy as np
import soundfile as sf
import torch
import torch.nn as nn
import torch.nn.functional as F

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_l2 as L2  # noqa: E402
import p1v4_score as S  # noqa: E402

WHISPER = "data/models_dl/whisper-base_e37978b"
EPOCHS, BATCH, WARMUP = 3, 32, 300
LR_ENC, LR_HEAD = 5e-5, 1e-3


class Windows(torch.utils.data.Dataset):
    def __init__(self, wins, X, y):
        self.wins, self.X, self.y = wins, X, y

    def __len__(self):
        return len(self.wins)

    def __getitem__(self, i):
        x = sf.read(self.wins[i]["path"], dtype="float32")[0]
        return torch.from_numpy(x), torch.from_numpy(self.X[i]), torch.from_numpy(self.y[i]), i


def loader(wins, X, y, shuffle, batch=BATCH, seed=0, workers=4):
    g = torch.Generator()
    g.manual_seed(seed)
    return torch.utils.data.DataLoader(Windows(wins, X, y), batch_size=batch, shuffle=shuffle, num_workers=workers,
                                       pin_memory=True, drop_last=shuffle, generator=g)


class Net(nn.Module):
    def __init__(self, n_feat):
        super().__init__()
        from transformers import WhisperFeatureExtractor, WhisperModel
        self.enc = WhisperModel.from_pretrained(WHISPER).encoder
        fe = WhisperFeatureExtractor.from_pretrained(WHISPER)
        self.register_buffer("filters", torch.tensor(fe.mel_filters, dtype=torch.float32), persistent=False)
        self.register_buffer("window", torch.hann_window(fe.n_fft), persistent=False)
        d = self.enc.config.d_model
        self.att = nn.Linear(d, 1)
        self.head = nn.Sequential(nn.Linear(d + n_feat, 256), nn.GELU(), nn.Linear(256, 2))

    def logmel(self, x):
        st = torch.stft(x, 400, 160, window=self.window, return_complex=True)
        mel = self.filters.T @ (st[..., :-1].abs() ** 2)
        lg = torch.clamp(mel, min=1e-10).log10()
        lg = torch.maximum(lg, lg.amax(dim=(-2, -1), keepdim=True) - 8.0)
        return (lg + 4.0) / 4.0

    def forward(self, x, feat):
        enc = self.enc
        h = F.gelu(enc.conv1(self.logmel(x.float())))
        h = F.gelu(enc.conv2(h)).permute(0, 2, 1)
        h = h + enc.embed_positions.weight[: h.shape[1]]
        for layer in enc.layers:
            h = layer(h, attention_mask=None)
            h = h[0] if isinstance(h, tuple) else h
        h = enc.layer_norm(h)
        a = self.att(h).float().softmax(1)
        pooled = (a * h.float()).sum(1)
        return self.head(torch.cat([pooled, feat.float()], 1))


def data(which, mu=None, sd=None):
    wins, rows, y = L2.labels(which)
    ids, X = L2.load_X(which, "t")
    assert ids == [w["id"] for w in wins]
    if mu is None:
        mu, sd = X.mean(0), X.std(0) + 1e-6
    return wins, rows, y, ((X - mu) / sd).astype(np.float32), mu, sd


@torch.no_grad()
def score(net, wins, X, y):
    net.eval()
    out = {}
    for x, f, _, idx in loader(wins, X, y, False, 64):
        with torch.autocast("cuda", dtype=torch.bfloat16):
            p = torch.sigmoid(net(x.cuda(non_blocking=True), f.cuda()).float()).cpu().numpy()
        for i, (ps, pr) in zip(idx.tolist(), p):
            w = wins[i]
            out[(w["unit"], w["version"], w["k"])] = {"S": float(ps), "R": float(pr)}
    return out


def rank(res):
    return (res["floors_met"], res["primary"], res["lowest_floor"])


def train(out_dir):
    os.makedirs(out_dir, exist_ok=True)
    D.gpu_guard()
    torch.manual_seed(0)
    tr, _, ytr, Xtr, mu, sd = data("train")
    keep = [i for i in range(len(tr)) if (ytr[i] >= 0).any()]
    tr, ytr, Xtr = [tr[i] for i in keep], ytr[keep], Xtr[keep]
    dv, dv_rows, ydv, Xdv, _, _ = data("dev", mu, sd)
    net = Net(Xtr.shape[1]).cuda()
    enc_p = list(net.enc.parameters())
    head_p = list(net.att.parameters()) + list(net.head.parameters())
    opt = torch.optim.AdamW([{"params": enc_p, "lr": LR_ENC}, {"params": head_p, "lr": LR_HEAD}], weight_decay=0.01)
    steps = EPOCHS * (len(tr) // BATCH)
    sched = torch.optim.lr_scheduler.LambdaLR(
        opt, lambda s: min(1.0, (s + 1) / WARMUP) * 0.5 * (1 + math.cos(math.pi * min(1.0, s / steps))))
    log, best, step = [], None, 0
    for ep in range(EPOCHS):
        net.train()
        t0, run = time.time(), []
        for x, f, yy, _ in loader(tr, Xtr, ytr, True, seed=ep):
            with torch.autocast("cuda", dtype=torch.bfloat16):
                lg = net(x.cuda(non_blocking=True), f.cuda())
            yy = yy.cuda()
            m = yy >= 0
            loss = F.binary_cross_entropy_with_logits(lg.float()[m], yy[m])
            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(net.parameters(), 1.0)
            opt.step()
            sched.step()
            step += 1
            run.append(loss.item())
            if step % 200 == 0:
                print(f"ep {ep} step {step}/{steps} loss {np.mean(run[-200:]):.4f} "
                      f"{(time.time() - t0) / len(run):.3f} s/step", flush=True)
        sc = score(net, dv, Xdv, ydv)
        res = S.operating_point(list(dv_rows.values()), sc)
        res.update(epoch=ep, train_loss=float(np.mean(run)), minutes=round((time.time() - t0) / 60, 1))
        log.append(res)
        print(json.dumps(res), flush=True)
        if best is None or rank(res) > rank(best):
            best = res
            torch.save({"state": net.state_dict(), "mu": mu, "sd": sd}, os.path.join(out_dir, "l3.pt"))
            json.dump({"|".join(map(str, k)): v for k, v in sc.items()},
                      open(os.path.join(out_dir, "scores_dev.json"), "w"))
        json.dump(log, open(os.path.join(out_dir, "train_log.json"), "w"), indent=1)
    print("kept epoch", best["epoch"], json.dumps(best))


if __name__ == "__main__":
    if sys.argv[1] == "train":
        train(sys.argv[2])
    else:
        raise SystemExit(__doc__)
